mapper.select:
/* IFacilityInfoMapper.selectAptCardList */ SELECT ac.apt_cmplex_no aptCmplexNo /* 단지번호 */ , ac.apt_cmplex_nm aptCmplexNm /* 단지명 */ , ac.sido_nm sidoNm /* 시도명 */ , ac.sigungu_nm sigunguNm /* 시군구명 */ , ac.dorojuso dorojuso /* 도로명주소 */ , ac.unit_cnt unitCnt /* 세대수 */ , ac.dong_cnt dongCnt /* 동수 */ , ac.bld_yr bldYr /* 준공년도 */ FROM apt_complex ac WHERE 1 = 1
AND ac.sido_nm = #{sidoNm}
AND ac.sigungu_nm = #{sigunguNm}
AND ac.apt_cmplex_nm LIKE '%' || #{keyword} || '%'
AND NVL(ac.unit_cnt, 0) < 300
AND NVL(ac.unit_cnt, 0) >= 300 AND NVL(ac.unit_cnt, 0) < 500
AND NVL(ac.unit_cnt, 0) >= 500 AND NVL(ac.unit_cnt, 0) < 1000
AND NVL(ac.unit_cnt, 0) >= 1000
ORDER BY ac.apt_cmplex_nm ASC
